// Calculate squared distance to avoid sqrt operation
auto squaredDistance = [&](const Point3D& a, const Point3D& b) {
    float_t dx = a.x - b.x;
    float_t dy = a.y - b.y;
    float_t dz = a.z - b.z;
    return dx*dx + dy*dy + dz*dz;
};

